INSERT INTO public.daily_challenge_bank
  (id, english, french, explanation, theme, difficulty, tiles, tile_keys, word_count, accepted_orders)
VALUES
  ('sr1', 'I like the red house.', 'J''aime la maison rouge.', 'In French, most adjectives (like ''rouge'') come AFTER the noun (''maison'').', 'Adjective Placement', 1, ARRAY['j''aime', 'la', 'maison', 'rouge', 'le', 'rouges']::text[], ARRAY['j''aime', 'la', 'maison', 'rouge', 'le', 'rouges']::text[], 4, '[["j''aime","la","maison","rouge"]]'::jsonb),
  ('sr2', 'I don''t eat meat.', 'Je ne mange pas de viande.', 'Negation in French uses the ''ne...pas'' sandwich around the verb.', 'Negation', 1, ARRAY['je', 'ne', 'mange', 'pas', 'de', 'viande', 'des', 'mangent']::text[], ARRAY['je', 'ne', 'mange', 'pas', 'de', 'viande', 'des', 'mangent']::text[], 6, '[["je","ne","mange","pas","de","viande"]]'::jsonb),
  ('sr3', 'He gives it to me.', 'Il me le donne.', 'Object pronouns (me, le) come BEFORE the verb in French.', 'Pronoun Placement', 2, ARRAY['il', 'me', 'le', 'donne', 'te', 'lui']::text[], ARRAY['il', 'me', 'le', 'donne', 'te', 'lui']::text[], 4, '[["il","me","le","donne"]]'::jsonb),
  ('sr21', 'I see her every day.', 'Je la vois tous les jours.', 'The object pronoun ''la'' (her/it) comes BEFORE the verb ''vois'', not after.', 'Pronoun Placement', 2, ARRAY['je', 'la', 'vois', 'tous', 'les', 'jours', 'le', 'voit']::text[], ARRAY['je', 'la', 'vois', 'tous', 'les', 'jours', 'le', 'voit']::text[], 6, '[["je","la","vois","tous","les","jours"],["tous","les","jours","je","la","vois"]]'::jsonb),
  ('sr22', 'We are talking to them.', 'Nous leur parlons.', '''Leur'' (to them) is an indirect object pronoun and goes BEFORE the verb, not after ''à eux''.', 'Pronoun Placement', 2, ARRAY['nous', 'leur', 'parlons', 'lui', 'parlez']::text[], ARRAY['nous', 'leur', 'parlons', 'lui', 'parlez']::text[], 3, '[["nous","leur","parlons"]]'::jsonb),
  ('sr4', 'I am going to the hospital.', 'Je vais à l''hôpital.', 'When ''à'' meets ''le'' before a vowel, it becomes ''à l''''.', 'Elision', 1, ARRAY['je', 'vais', 'à', 'l''hôpital', 'au', 'allez']::text[], ARRAY['je', 'vais', 'à', 'l''hôpital', 'au', 'allez']::text[], 4, '[["je","vais","à","l''hôpital"]]'::jsonb),
  ('sr5', 'We have many friends.', 'Nous avons beaucoup d''amis.', '''Beaucoup'' always takes ''de'' (or d'' before a vowel), never ''des''.', 'Prepositions', 2, ARRAY['nous', 'avons', 'beaucoup', 'd''amis', 'des', 'avez']::text[], ARRAY['nous', 'avons', 'beaucoup', 'd''amis', 'des', 'avez']::text[], 4, '[["nous","avons","beaucoup","d''amis"]]'::jsonb),
  ('sr6', 'I am happy that you are here.', 'Je suis content que tu sois là.', 'Expressions of emotion (like ''content que'') trigger the Subjunctive mood (''sois'').', 'Subjunctive', 3, ARRAY['je', 'suis', 'content', 'que', 'tu', 'sois', 'là', 'es', 'soit']::text[], ARRAY['je', 'suis', 'content', 'que', 'tu', 'sois', 'là', 'es', 'soit']::text[], 7, '[["je","suis","content","que","tu","sois","là"]]'::jsonb),
  ('sr7', 'The book that I bought is good.', 'Le livre que j''ai acheté est bon.', '''Que'' is used as a relative pronoun when it''s the object of the following verb.', 'Relative Pronouns', 2, ARRAY['le', 'livre', 'que', 'j''ai', 'acheté', 'est', 'bon', 'qui', 'achetée']::text[], ARRAY['le', 'livre', 'que', 'j''ai', 'acheté', 'est', 'bon', 'qui', 'achetée']::text[], 7, '[["le","livre","que","j''ai","acheté","est","bon"]]'::jsonb),
  ('sr8', 'I used to play in the park.', 'Je jouais dans le parc.', 'The Imparfait (''jouais'') is used for habitual actions in the past.', 'Imperfect Tense', 2, ARRAY['je', 'jouais', 'dans', 'le', 'parc', 'joue', 'au']::text[], ARRAY['je', 'jouais', 'dans', 'le', 'parc', 'joue', 'au']::text[], 5, '[["je","jouais","dans","le","parc"]]'::jsonb),
  ('sr9', 'If it rains, we will stay at home.', 'S''il pleut, nous resterons à la maison.', 'The ''Si'' clause uses the Present tense, and the main clause uses the Future tense.', 'Conditionals', 3, ARRAY['s''il', 'pleut', 'nous', 'resterons', 'à', 'la', 'maison', 'pleuvra', 'resterions']::text[], ARRAY['s''il', 'pleut', 'nous', 'resterons', 'à', 'la', 'maison', 'pleuvra', 'resterions']::text[], 7, '[["s''il","pleut","nous","resterons","à","la","maison"],["nous","resterons","à","la","maison","s''il","pleut"]]'::jsonb),
  ('sr10', 'I am looking for my keys.', 'Je cherche mes clés.', 'The verb ''chercher'' means ''to look FOR'', so no extra preposition is needed.', 'Verb Patterns', 1, ARRAY['je', 'cherche', 'mes', 'clés', 'pour', 'cherches']::text[], ARRAY['je', 'cherche', 'mes', 'clés', 'pour', 'cherches']::text[], 4, '[["je","cherche","mes","clés"]]'::jsonb),
  ('sr11', 'I washed my hands.', 'Je me suis lavé les mains.', 'Reflexive verbs use ''être'' in the Passé Composé. ''Me suis lavé'' means ''I washed myself''.', 'Reflexive Verbs', 2, ARRAY['je', 'me', 'suis', 'lavé', 'les', 'mains', 'ai', 'laver']::text[], ARRAY['je', 'me', 'suis', 'lavé', 'les', 'mains', 'ai', 'laver']::text[], 6, '[["je","me","suis","lavé","les","mains"]]'::jsonb),
  ('sr12', 'If I was rich, I would buy a boat.', 'Si j''étais riche, j''achèterais un bateau.', 'The ''Si'' clause uses the Imparfait, and the main clause uses the Conditionnel.', 'Conditionals', 3, ARRAY['si', 'j''étais', 'riche', 'j''achèterais', 'un', 'bateau', 'serais', 'achèterai']::text[], ARRAY['si', 'j''étais', 'riche', 'j''achèterais', 'un', 'bateau', 'serais', 'achèterai']::text[], 6, '[["si","j''étais","riche","j''achèterais","un","bateau"],["j''achèterais","un","bateau","si","j''étais","riche"]]'::jsonb),
  ('sr13', 'I have to go there.', 'Je dois y aller.', 'The pronoun ''y'' replaces a place and usually comes before the infinitive.', 'Pronoun ''Y''', 2, ARRAY['je', 'dois', 'y', 'aller', 'en', 'doit']::text[], ARRAY['je', 'dois', 'y', 'aller', 'en', 'doit']::text[], 4, '[["je","dois","y","aller"]]'::jsonb),
  ('sr14', 'What are you doing tonight?', 'Qu''est-ce que tu fais ce soir ?', '''Qu''est-ce que'' is a very common way to start a question meaning ''What...''.', 'Questions', 1, ARRAY['qu''est-ce', 'que', 'tu', 'fais', 'ce', 'soir', '?', 'fait', 'cette']::text[], ARRAY['qu''est-ce', 'que', 'tu', 'fais', 'ce', 'soir', '?', 'fait', 'cette']::text[], 7, '[["qu''est-ce","que","tu","fais","ce","soir","?"]]'::jsonb),
  ('sr15', 'I think that he is right.', 'Je pense qu''il a raison.', 'In French, you don''t say ''is right'', you say ''has reason'' (avoir raison).', 'Idiomatic Expressions', 2, ARRAY['je', 'pense', 'qu''il', 'a', 'raison', 'est', 'pensent']::text[], ARRAY['je', 'pense', 'qu''il', 'a', 'raison', 'est', 'pensent']::text[], 5, '[["je","pense","qu''il","a","raison"]]'::jsonb),
  ('sr16', 'Don''t speak to me like that.', 'Ne me parle pas comme ça.', 'In negative imperatives, the object pronoun ''me'' comes before the verb.', 'Imperatives', 2, ARRAY['ne', 'me', 'parle', 'pas', 'comme', 'ça', 'moi', 'parler']::text[], ARRAY['ne', 'me', 'parle', 'pas', 'comme', 'ça', 'moi', 'parler']::text[], 6, '[["ne","me","parle","pas","comme","ça"]]'::jsonb),
  ('sr17', 'The car which I saw is black.', 'La voiture que j''ai vue est noire.', 'When ''que'' is a direct object before ''avoir'', the past participle agrees with the noun.', 'Past Participle Agreement', 3, ARRAY['la', 'voiture', 'que', 'j''ai', 'vue', 'est', 'noire', 'vu', 'noir']::text[], ARRAY['la', 'voiture', 'que', 'j''ai', 'vue', 'est', 'noire', 'vu', 'noir']::text[], 7, '[["la","voiture","que","j''ai","vue","est","noire"]]'::jsonb),
  ('sr18', 'I''m going to do my homework.', 'Je vais faire mes devoirs.', 'The Futur Proche uses ''aller'' + infinitive.', 'Future Tenses', 1, ARRAY['je', 'vais', 'faire', 'mes', 'devoirs', 'ses', 'allons']::text[], ARRAY['je', 'vais', 'faire', 'mes', 'devoirs', 'ses', 'allons']::text[], 5, '[["je","vais","faire","mes","devoirs"]]'::jsonb),
  ('sr19', 'She is taller than him.', 'Elle est plus grande que lui.', 'Comparatives use ''plus + adjective + que''.', 'Comparatives', 1, ARRAY['elle', 'est', 'plus', 'grande', 'que', 'lui', 'grand', 'elles']::text[], ARRAY['elle', 'est', 'plus', 'grande', 'que', 'lui', 'grand', 'elles']::text[], 6, '[["elle","est","plus","grande","que","lui"]]'::jsonb),
  ('sr20', 'I will call you as soon as I arrive.', 'Je t''appellerai dès que j''arriverai.', 'After ''dès que'', French uses the future tense if the main verb is in the future.', 'Future Tenses', 3, ARRAY['je', 't''appellerai', 'dès', 'que', 'j''arriverai', 'arrivais', 'appelais']::text[], ARRAY['je', 't''appellerai', 'dès', 'que', 'j''arriverai', 'arrivais', 'appelais']::text[], 5, '[["je","t''appellerai","dès","que","j''arriverai"],["dès","que","j''arriverai","je","t''appellerai"]]'::jsonb),
  ('sr23', 'I need a pen.', 'J''ai besoin d''un stylo.', '''De'' contracts to d'' before a vowel — ''de un'' is never correct.', 'Elision', 1, ARRAY['j''ai', 'besoin', 'd''un', 'stylo', 'de', 'un']::text[], ARRAY['j''ai', 'besoin', 'd''un', 'stylo', 'de', 'un']::text[], 4, '[["j''ai","besoin","d''un","stylo"]]'::jsonb),
  ('sr24', 'This hotel is magnificent.', 'Cet hôtel est magnifique.', 'Masculine ''ce'' becomes ''cet'' before a vowel or mute h, for phonetic ease.', 'Elision', 1, ARRAY['cet', 'hôtel', 'est', 'magnifique', 'ce', 'magnifiques']::text[], ARRAY['cet', 'hôtel', 'est', 'magnifique', 'ce', 'magnifiques']::text[], 4, '[["cet","hôtel","est","magnifique"]]'::jsonb),
  ('sr25', 'I don''t have any money.', 'Je n''ai pas d''argent.', 'Formal negation keeps both ''ne'' and ''pas'' around the verb, even in speech.', 'Negation', 1, ARRAY['je', 'n''ai', 'pas', 'd''argent', 'du', 'ne']::text[], ARRAY['je', 'n''ai', 'pas', 'd''argent', 'du', 'ne']::text[], 4, '[["je","n''ai","pas","d''argent"]]'::jsonb),
  ('sr26', 'He never goes to school on Saturday.', 'Il ne va jamais à l''école le samedi.', '''Ne...jamais'' (''never'') follows the same sandwich pattern as ''ne...pas''.', 'Negation', 2, ARRAY['il', 'ne', 'va', 'jamais', 'à', 'l''école', 'le', 'samedi', 'pas', 'au']::text[], ARRAY['il', 'ne', 'va', 'jamais', 'à', 'l''école', 'le', 'samedi', 'pas', 'au']::text[], 8, '[["il","ne","va","jamais","à","l''école","le","samedi"],["le","samedi","il","ne","va","jamais","à","l''école"]]'::jsonb),
  ('sr27', 'It''s important that you come tomorrow.', 'Il est important que tu viennes demain.', '''Il est important que'' expresses necessity and triggers the subjunctive (''viennes'').', 'Subjunctive', 3, ARRAY['il', 'est', 'important', 'que', 'tu', 'viennes', 'demain', 'viens', 'soit']::text[], ARRAY['il', 'est', 'important', 'que', 'tu', 'viennes', 'demain', 'viens', 'soit']::text[], 7, '[["il","est","important","que","tu","viennes","demain"]]'::jsonb),
  ('sr28', 'I doubt that he knows the answer.', 'Je doute qu''il sache la réponse.', '''Douter que'' expresses doubt and requires the subjunctive (''sache'', from savoir).', 'Subjunctive', 3, ARRAY['je', 'doute', 'qu''il', 'sache', 'la', 'réponse', 'sait', 'les']::text[], ARRAY['je', 'doute', 'qu''il', 'sache', 'la', 'réponse', 'sait', 'les']::text[], 6, '[["je","doute","qu''il","sache","la","réponse"]]'::jsonb),
  ('sr29', 'The teacher who explains well is popular.', 'Le professeur qui explique bien est populaire.', '''Qui'' is the subject of ''explique'' here, so it stays as ''qui'', not ''que''.', 'Relative Pronouns', 2, ARRAY['le', 'professeur', 'qui', 'explique', 'bien', 'est', 'populaire', 'que', 'populaires']::text[], ARRAY['le', 'professeur', 'qui', 'explique', 'bien', 'est', 'populaire', 'que', 'populaires']::text[], 7, '[["le","professeur","qui","explique","bien","est","populaire"]]'::jsonb),
  ('sr30', 'The town where I was born is small.', 'La ville où je suis né est petite.', '''Où'' is used as a relative pronoun for places, even when ''where'' isn''t literal in English.', 'Relative Pronouns', 2, ARRAY['la', 'ville', 'où', 'je', 'suis', 'né', 'est', 'petite', 'que', 'petit']::text[], ARRAY['la', 'ville', 'où', 'je', 'suis', 'né', 'est', 'petite', 'que', 'petit']::text[], 8, '[["la","ville","où","je","suis","né","est","petite"]]'::jsonb),
  ('sr31', 'My sister is tall.', 'Ma sœur est grande.', 'Feminine adjectives usually add -e: ''grand'' becomes ''grande'' to agree with ''sœur''.', 'Adjective Placement', 1, ARRAY['ma', 'sœur', 'est', 'grande', 'mon', 'grand']::text[], ARRAY['ma', 'sœur', 'est', 'grande', 'mon', 'grand']::text[], 4, '[["ma","sœur","est","grande"]]'::jsonb),
  ('sr32', 'It''s a new car.', 'C''est une nouvelle voiture.', '''Nouveau'' is irregular in the feminine: ''nouvelle'', and placed before the noun.', 'Adjective Placement', 2, ARRAY['c''est', 'une', 'nouvelle', 'voiture', 'nouveau', 'un']::text[], ARRAY['c''est', 'une', 'nouvelle', 'voiture', 'nouveau', 'un']::text[], 4, '[["c''est","une","nouvelle","voiture"]]'::jsonb),
  ('sr33', 'This dress is beautiful.', 'Cette robe est belle.', '''Cette'' is the feminine singular demonstrative, used before a feminine noun like ''robe''.', 'Demonstratives', 1, ARRAY['cette', 'robe', 'est', 'belle', 'ce', 'beau']::text[], ARRAY['cette', 'robe', 'est', 'belle', 'ce', 'beau']::text[], 4, '[["cette","robe","est","belle"]]'::jsonb),
  ('sr34', 'These books are interesting.', 'Ces livres sont intéressants.', '''Ces'' is the plural demonstrative, used for both masculine and feminine plural nouns.', 'Demonstratives', 1, ARRAY['ces', 'livres', 'sont', 'intéressants', 'ce', 'intéressant']::text[], ARRAY['ces', 'livres', 'sont', 'intéressants', 'ce', 'intéressant']::text[], 4, '[["ces","livres","sont","intéressants"]]'::jsonb),
  ('sr35', 'I prefer this one (m).', 'Je préfère celui-ci.', '''Celui-ci'' (''this one'') replaces a masculine noun already mentioned.', 'Demonstratives', 2, ARRAY['je', 'préfère', 'celui-ci', 'préfères', 'celles-ci']::text[], ARRAY['je', 'préfère', 'celui-ci', 'préfères', 'celles-ci']::text[], 3, '[["je","préfère","celui-ci"]]'::jsonb),
  ('sr36', 'This film is better than the last one.', 'Ce film est meilleur que le dernier.', '''Bon'' has an irregular comparative: ''meilleur'', never ''plus bon''.', 'Comparatives', 2, ARRAY['ce', 'film', 'est', 'meilleur', 'que', 'le', 'dernier', 'plus', 'bon']::text[], ARRAY['ce', 'film', 'est', 'meilleur', 'que', 'le', 'dernier', 'plus', 'bon']::text[], 7, '[["ce","film","est","meilleur","que","le","dernier"]]'::jsonb),
  ('sr37', 'He speaks better than his brother.', 'Il parle mieux que son frère.', '''Bien'' has an irregular comparative adverb: ''mieux'', never ''plus bien''.', 'Comparatives', 2, ARRAY['il', 'parle', 'mieux', 'que', 'son', 'frère', 'meilleur', 'sa']::text[], ARRAY['il', 'parle', 'mieux', 'que', 'son', 'frère', 'meilleur', 'sa']::text[], 6, '[["il","parle","mieux","que","son","frère"]]'::jsonb),
  ('sr38', 'I am listening to the radio.', 'J''écoute la radio.', '''Écouter'' is a direct transitive verb in French — no preposition, unlike English ''listen TO''.', 'Prepositions', 1, ARRAY['j''écoute', 'la', 'radio', 'à', 'le']::text[], ARRAY['j''écoute', 'la', 'radio', 'à', 'le']::text[], 3, '[["j''écoute","la","radio"]]'::jsonb),
  ('sr39', 'I used to live in Paris.', 'J''habitais à Paris.', 'The Imparfait (''habitais'') describes an ongoing past state, not a single completed action.', 'Imperfect Tense', 2, ARRAY['j''habitais', 'à', 'Paris', 'habite', 'en']::text[], ARRAY['j''habitais', 'à', 'paris', 'habite', 'en']::text[], 3, '[["j''habitais","à","paris"]]'::jsonb),
  ('sr40', 'We got up early.', 'Nous nous sommes levés tôt.', 'Reflexive verbs always take ''être'' in the Passé Composé, agreeing with the subject.', 'Reflexive Verbs', 2, ARRAY['nous', 'nous', 'sommes', 'levés', 'tôt', 'avons', 'lever']::text[], ARRAY['nous', 'nous', 'sommes', 'levés', 'tôt', 'avons', 'lever']::text[], 5, '[["nous","nous","sommes","levés","tôt"]]'::jsonb),
  ('sr41', 'If I won the lottery, I would travel the world.', 'Si je gagnais au loto, je voyagerais autour du monde.', 'Si + imparfait pairs with the conditional in the main clause, not the future.', 'Conditionals', 3, ARRAY['si', 'je', 'gagnais', 'au', 'loto', 'je', 'voyagerais', 'autour', 'du', 'monde', 'gagnerais', 'voyagerai']::text[], ARRAY['si', 'je', 'gagnais', 'au', 'loto', 'je', 'voyagerais', 'autour', 'du', 'monde', 'gagnerais', 'voyagerai']::text[], 10, '[["si","je","gagnais","au","loto","je","voyagerais","autour","du","monde"],["je","voyagerais","autour","du","monde","si","je","gagnais","au","loto"]]'::jsonb),
  ('sr42', 'I go to school by bus.', 'Je vais à l''école en bus.', 'Transport takes ''en'' (en bus, en train, en voiture), but ''à'' for bikes and walking (à vélo, à pied).', 'Prepositions', 1, ARRAY['je', 'vais', 'à', 'l''école', 'en', 'bus', 'au', 'dans']::text[], ARRAY['je', 'vais', 'à', 'l''école', 'en', 'bus', 'au', 'dans']::text[], 6, '[["je","vais","à","l''école","en","bus"]]'::jsonb),
  ('sr43', 'My brother is eleven years old.', 'Mon frère a onze ans.', 'French uses ''avoir'' (to have) for age, never ''être'': he HAS eleven years.', 'Verb Patterns', 1, ARRAY['mon', 'frère', 'a', 'onze', 'ans', 'est', 'ma']::text[], ARRAY['mon', 'frère', 'a', 'onze', 'ans', 'est', 'ma']::text[], 5, '[["mon","frère","a","onze","ans"]]'::jsonb),
  ('sr44', 'Where do you live?', 'Où est-ce que tu habites ?', 'Question word + ''est-ce que'' + the normal word order is the easiest way to ask a question.', 'Questions', 1, ARRAY['où', 'est-ce', 'que', 'tu', 'habites', '?', 'habite', 'quand']::text[], ARRAY['où', 'est-ce', 'que', 'tu', 'habites', '?', 'habite', 'quand']::text[], 6, '[["où","est-ce","que","tu","habites","?"]]'::jsonb),
  ('sr45', 'I like playing football.', 'J''aime jouer au football.', 'Sports take ''jouer à'' (au = à + le); instruments take ''jouer de'' (jouer de la guitare).', 'Prepositions', 1, ARRAY['j''aime', 'jouer', 'au', 'football', 'du', 'à']::text[], ARRAY['j''aime', 'jouer', 'au', 'football', 'du', 'à']::text[], 4, '[["j''aime","jouer","au","football"]]'::jsonb),
  ('sr46', 'She has a big dog.', 'Elle a un grand chien.', 'Short, common adjectives of beauty, age, goodness and size (BAGS) like ''grand'' go BEFORE the noun.', 'Adjective Placement', 1, ARRAY['elle', 'a', 'un', 'grand', 'chien', 'une', 'grande']::text[], ARRAY['elle', 'a', 'un', 'grand', 'chien', 'une', 'grande']::text[], 5, '[["elle","a","un","grand","chien"]]'::jsonb),
  ('sr47', 'We don''t have any homework.', 'Nous n''avons pas de devoirs.', 'After a negative, ''des'', ''du'' and ''un'' all become ''de'' (or d'' before a vowel): pas de devoirs.', 'Negation', 1, ARRAY['nous', 'n''avons', 'pas', 'de', 'devoirs', 'des', 'ne']::text[], ARRAY['nous', 'n''avons', 'pas', 'de', 'devoirs', 'des', 'ne']::text[], 5, '[["nous","n''avons","pas","de","devoirs"]]'::jsonb),
  ('sr48', 'Yesterday I ate at the restaurant.', 'Hier, j''ai mangé au restaurant.', 'The passé composé of most verbs is ''avoir'' + past participle: j''ai mangé. ''Hier'' signals a finished action.', 'Perfect Tense', 2, ARRAY['hier', 'j''ai', 'mangé', 'au', 'restaurant', 'suis', 'mange']::text[], ARRAY['hier', 'j''ai', 'mangé', 'au', 'restaurant', 'suis', 'mange']::text[], 5, '[["hier","j''ai","mangé","au","restaurant"],["j''ai","mangé","au","restaurant","hier"]]'::jsonb),
  ('sr49', 'Last weekend I went to the cinema.', 'Le week-end dernier, je suis allé au cinéma.', '''Aller'' is one of the verbs that take ''être'' in the perfect tense, so the participle agrees with you: allé (allée if you are female).', 'Perfect Tense', 2, ARRAY['le', 'week-end', 'dernier', 'je', 'suis', 'allé', 'au', 'cinéma', 'ai', 'vais']::text[], ARRAY['le', 'week-end', 'dernier', 'je', 'suis', 'allé', 'au', 'cinéma', 'ai', 'vais']::text[], 8, '[["le","week-end","dernier","je","suis","allé","au","cinéma"],["je","suis","allé","au","cinéma","le","week-end","dernier"]]'::jsonb),
  ('sr50', 'Next year I will go to France.', 'L''année prochaine, j''irai en France.', '''Aller'' has an irregular future stem, ir-: j''irai. Feminine countries take ''en'' for ''to'' and ''in''.', 'Future Tenses', 2, ARRAY['l''année', 'prochaine', 'j''irai', 'en', 'France', 'à', 'vais']::text[], ARRAY['l''année', 'prochaine', 'j''irai', 'en', 'france', 'à', 'vais']::text[], 5, '[["l''année","prochaine","j''irai","en","france"],["j''irai","en","france","l''année","prochaine"]]'::jsonb),
  ('sr51', 'In my opinion, it is too expensive.', 'À mon avis, c''est trop cher.', '''À mon avis'' gives an opinion without needing a verb. Careful: ''trop'' means too (much), ''très'' means very.', 'Opinions', 1, ARRAY['à', 'mon', 'avis', 'c''est', 'trop', 'cher', 'très', 'beaucoup']::text[], ARRAY['à', 'mon', 'avis', 'c''est', 'trop', 'cher', 'très', 'beaucoup']::text[], 6, '[["à","mon","avis","c''est","trop","cher"],["c''est","trop","cher","à","mon","avis"]]'::jsonb),
  ('sr52', 'I prefer sport because it is fun.', 'Je préfère le sport parce que c''est amusant.', '''Parce que'' introduces a reason and is followed by a full clause with its own verb: parce que c''est amusant.', 'Opinions', 2, ARRAY['je', 'préfère', 'le', 'sport', 'parce', 'que', 'c''est', 'amusant', 'pour', 'car']::text[], ARRAY['je', 'préfère', 'le', 'sport', 'parce', 'que', 'c''est', 'amusant', 'pour', 'car']::text[], 8, '[["je","préfère","le","sport","parce","que","c''est","amusant"]]'::jsonb),
  ('sr53', 'My mother works in a hospital.', 'Ma mère travaille dans un hôpital.', 'Use ''dans'' for ''in'' a building or a place you are inside; ''à'' is for ''at'' or ''to'' a town.', 'Prepositions', 1, ARRAY['ma', 'mère', 'travaille', 'dans', 'un', 'hôpital', 'mon', 'travailles']::text[], ARRAY['ma', 'mère', 'travaille', 'dans', 'un', 'hôpital', 'mon', 'travailles']::text[], 6, '[["ma","mère","travaille","dans","un","hôpital"]]'::jsonb),
  ('sr54', 'He isn''t at home because he is ill.', 'Il n''est pas à la maison parce qu''il est malade.', '''Parce que'' shortens to ''parce qu'''' in front of il, elle, on and a vowel. The ne...pas sandwich wraps ''est''.', 'Negation', 2, ARRAY['il', 'n''est', 'pas', 'à', 'la', 'maison', 'parce', 'qu''il', 'est', 'malade', 'que', 'ne']::text[], ARRAY['il', 'n''est', 'pas', 'à', 'la', 'maison', 'parce', 'qu''il', 'est', 'malade', 'que', 'ne']::text[], 10, '[["il","n''est","pas","à","la","maison","parce","qu''il","est","malade"],["parce","qu''il","est","malade","il","n''est","pas","à","la","maison"]]'::jsonb),
  ('sr55', 'Can you help me, please?', 'Pouvez-vous m''aider, s''il vous plaît ?', 'Turning the verb and ''vous'' round (pouvez-vous) is the polite way to ask. ''Me'' drops to m'' before a vowel.', 'Questions', 2, ARRAY['pouvez-vous', 'm''aider', 's''il', 'vous', 'plaît', '?', 'aide', 'me']::text[], ARRAY['pouvez-vous', 'm''aider', 's''il', 'vous', 'plaît', '?', 'aide', 'me']::text[], 6, '[["pouvez-vous","m''aider","s''il","vous","plaît","?"]]'::jsonb),
  ('sr56', 'She is going to buy a new bag.', 'Elle va acheter un nouveau sac.', 'Futur proche: ''aller'' + infinitive. ''Nouveau'' goes before the noun and has a feminine form, ''nouvelle'', for words like ''robe''.', 'Future Tenses', 1, ARRAY['elle', 'va', 'acheter', 'un', 'nouveau', 'sac', 'nouvelle', 'une']::text[], ARRAY['elle', 'va', 'acheter', 'un', 'nouveau', 'sac', 'nouvelle', 'une']::text[], 6, '[["elle","va","acheter","un","nouveau","sac"]]'::jsonb),
  ('sr57', 'I would like to go to the beach if it is sunny.', 'Je voudrais aller à la plage s''il fait beau.', '''Je voudrais'' (conditional of vouloir) is the polite ''I would like''. ''Si'' becomes ''s'''' in front of ''il''.', 'Conditionals', 2, ARRAY['je', 'voudrais', 'aller', 'à', 'la', 'plage', 's''il', 'fait', 'beau', 'au', 'ferai']::text[], ARRAY['je', 'voudrais', 'aller', 'à', 'la', 'plage', 's''il', 'fait', 'beau', 'au', 'ferai']::text[], 9, '[["je","voudrais","aller","à","la","plage","s''il","fait","beau"],["s''il","fait","beau","je","voudrais","aller","à","la","plage"]]'::jsonb),
  ('sr58', 'I have never been to Spain.', 'Je ne suis jamais allé en Espagne.', 'In the perfect tense, ne...jamais wraps the auxiliary (suis) and the participle comes last. (Allée if you are female.)', 'Negation', 2, ARRAY['je', 'ne', 'suis', 'jamais', 'allé', 'en', 'Espagne', 'ai', 'à']::text[], ARRAY['je', 'ne', 'suis', 'jamais', 'allé', 'en', 'espagne', 'ai', 'à']::text[], 7, '[["je","ne","suis","jamais","allé","en","espagne"]]'::jsonb),
  ('sr59', 'When I was little, I played with my cousins.', 'Quand j''étais petit, je jouais avec mes cousins.', 'Both verbs are in the imparfait: it sets the scene and describes what used to happen when you were small.', 'Imperfect Tense', 2, ARRAY['quand', 'j''étais', 'petit', 'je', 'jouais', 'avec', 'mes', 'cousins', 'jouerai', 'ma']::text[], ARRAY['quand', 'j''étais', 'petit', 'je', 'jouais', 'avec', 'mes', 'cousins', 'jouerai', 'ma']::text[], 8, '[["quand","j''étais","petit","je","jouais","avec","mes","cousins"],["je","jouais","avec","mes","cousins","quand","j''étais","petit"]]'::jsonb),
  ('sr60', 'The film that we watched was really funny.', 'Le film que nous avons regardé était vraiment drôle.', '''Que'' is the object of ''avons regardé'', so it stays ''que''. ''Était'' (imparfait) describes how the film was.', 'Relative Pronouns', 2, ARRAY['le', 'film', 'que', 'nous', 'avons', 'regardé', 'était', 'vraiment', 'drôle', 'qui', 'regardés']::text[], ARRAY['le', 'film', 'que', 'nous', 'avons', 'regardé', 'était', 'vraiment', 'drôle', 'qui', 'regardés']::text[], 9, '[["le","film","que","nous","avons","regardé","était","vraiment","drôle"]]'::jsonb),
  ('sr61', 'I am afraid that it will rain tomorrow.', 'J''ai peur qu''il pleuve demain.', '''Avoir peur que'' (fear) triggers the subjunctive: ''pleuve'' comes from pleuvoir. Never ''pleuvra'' here.', 'Subjunctive', 3, ARRAY['j''ai', 'peur', 'qu''il', 'pleuve', 'demain', 'pleut', 'pleuvra']::text[], ARRAY['j''ai', 'peur', 'qu''il', 'pleuve', 'demain', 'pleut', 'pleuvra']::text[], 5, '[["j''ai","peur","qu''il","pleuve","demain"]]'::jsonb),
  ('sr62', 'Do you want to come to my house on Saturday?', 'Veux-tu venir chez moi samedi ?', '''Chez moi'' means ''at my place''. A day with no article (''samedi'') means this coming Saturday.', 'Questions', 2, ARRAY['veux-tu', 'venir', 'chez', 'moi', 'samedi', '?', 'à', 'viens']::text[], ARRAY['veux-tu', 'venir', 'chez', 'moi', 'samedi', '?', 'à', 'viens']::text[], 6, '[["veux-tu","venir","chez","moi","samedi","?"],["samedi","veux-tu","venir","chez","moi","?"]]'::jsonb),
  ('sr63', 'There are too many cars in my town.', 'Il y a trop de voitures dans ma ville.', 'Quantity words (trop, beaucoup, assez) are followed by ''de'' with no article: trop de voitures.', 'Quantities', 2, ARRAY['il', 'y', 'a', 'trop', 'de', 'voitures', 'dans', 'ma', 'ville', 'des', 'mon']::text[], ARRAY['il', 'y', 'a', 'trop', 'de', 'voitures', 'dans', 'ma', 'ville', 'des', 'mon']::text[], 9, '[["il","y","a","trop","de","voitures","dans","ma","ville"],["dans","ma","ville","il","y","a","trop","de","voitures"]]'::jsonb),
  ('sr64', 'My favourite subject is history.', 'Ma matière préférée est l''histoire.', '''Préféré'' goes after the noun and agrees with it: ''matière'' is feminine, so préférée.', 'Adjective Placement', 1, ARRAY['ma', 'matière', 'préférée', 'est', 'l''histoire', 'préféré', 'mon']::text[], ARRAY['ma', 'matière', 'préférée', 'est', 'l''histoire', 'préféré', 'mon']::text[], 5, '[["ma","matière","préférée","est","l''histoire"]]'::jsonb),
  ('sr65', 'She wants to become a doctor.', 'Elle veut devenir médecin.', 'After ''être'' or ''devenir'', a job is used without ''un/une'': elle veut devenir médecin.', 'Verb Patterns', 1, ARRAY['elle', 'veut', 'devenir', 'médecin', 'voulons', 'devient']::text[], ARRAY['elle', 'veut', 'devenir', 'médecin', 'voulons', 'devient']::text[], 4, '[["elle","veut","devenir","médecin"]]'::jsonb)
